const videoRooms = `-- name: VideoRooms :many
SELECT r.id, r.uuid, r.organization_id, r.name, r.livekit_name, r.status, r.host_user_id, r.created_by, r.appointment_uuid, r.conversation_id, r.pin_enc, r.lobby, r.guest_join, r.e2ee, r.e2ee_key_enc, r.recording, r.allow_camera, r.allow_screen_share, r.allow_chat, r.max_participants, r.max_duration_minutes, r.scheduled_start_at, r.scheduled_end_at, r.links_expire_at, r.started_at, r.ended_at, r.billed_minutes, r.unbilled_minutes, r.created_at, r.updated_at,c.uuid AS conversation_uuid,
(SELECT count(*) FROM video_participants p WHERE p.organization_id=r.organization_id AND p.room_id=r.id AND p.status='waiting')::bigint AS waiting
FROM video_rooms r LEFT JOIN conversations c ON c.organization_id=r.organization_id AND c.id=r.conversation_id
WHERE r.organization_id=$1 AND ($2::text IS NULL OR r.status=$2::text)
ORDER BY r.id DESC LIMIT $4 OFFSET $3
`

type VideoRoomsParams struct {
	OrganizationID int64       `json:"organization_id"`
	Status         pgtype.Text `json:"status"`
	RowOffset      int32       `json:"row_offset"`
	RowLimit       int32       `json:"row_limit"`
}

type VideoRoomsRow struct {
	ID                 int64              `json:"id"`
	Uuid               uuid.UUID          `json:"uuid"`
	OrganizationID     int64              `json:"organization_id"`
	Name               string             `json:"name"`
	LivekitName        string             `json:"livekit_name"`
	Status             string             `json:"status"`
	HostUserID         pgtype.Int8        `json:"host_user_id"`
	CreatedBy          pgtype.Int8        `json:"created_by"`
	AppointmentUuid    pgtype.UUID        `json:"appointment_uuid"`
	ConversationID     pgtype.Int8        `json:"conversation_id"`
	PinEnc             string             `json:"pin_enc"`
	Lobby              bool               `json:"lobby"`
	GuestJoin          bool               `json:"guest_join"`
	E2ee               bool               `json:"e2ee"`
	E2eeKeyEnc         string             `json:"e2ee_key_enc"`
	Recording          bool               `json:"recording"`
	AllowCamera        bool               `json:"allow_camera"`
	AllowScreenShare   bool               `json:"allow_screen_share"`
	AllowChat          bool               `json:"allow_chat"`
	MaxParticipants    int32              `json:"max_participants"`
	MaxDurationMinutes int32              `json:"max_duration_minutes"`
	ScheduledStartAt   pgtype.Timestamptz `json:"scheduled_start_at"`
	ScheduledEndAt     pgtype.Timestamptz `json:"scheduled_end_at"`
	LinksExpireAt      pgtype.Timestamptz `json:"links_expire_at"`
	StartedAt          pgtype.Timestamptz `json:"started_at"`
	EndedAt            pgtype.Timestamptz `json:"ended_at"`
	BilledMinutes      int64              `json:"billed_minutes"`
	UnbilledMinutes    int64              `json:"unbilled_minutes"`
	CreatedAt          pgtype.Timestamptz `json:"created_at"`
	UpdatedAt          pgtype.Timestamptz `json:"updated_at"`
	ConversationUuid   pgtype.UUID        `json:"conversation_uuid"`
	Waiting            int64              `json:"waiting"`
}

func (q *Queries) VideoRooms(ctx context.Context, arg VideoRoomsParams) ([]VideoRoomsRow, error) {
	rows, err := q.db.Query(ctx, videoRooms,
		arg.OrganizationID,
		arg.Status,
		arg.RowOffset,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VideoRoomsRow{}
	for rows.Next() {
		var i VideoRoomsRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.Name,
			&i.LivekitName,
			&i.Status,
			&i.HostUserID,
			&i.CreatedBy,
			&i.AppointmentUuid,
			&i.ConversationID,
			&i.PinEnc,
			&i.Lobby,
			&i.GuestJoin,
			&i.E2ee,
			&i.E2eeKeyEnc,
			&i.Recording,
			&i.AllowCamera,
			&i.AllowScreenShare,
			&i.AllowChat,
			&i.MaxParticipants,
			&i.MaxDurationMinutes,
			&i.ScheduledStartAt,
			&i.ScheduledEndAt,
			&i.LinksExpireAt,
			&i.StartedAt,
			&i.EndedAt,
			&i.BilledMinutes,
			&i.UnbilledMinutes,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ConversationUuid,
			&i.Waiting,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

